import { useEffect, useState } from "react";

export default function AdminPage() {
  const [orders, setOrders] = useState([]);
  const [menu, setMenu] = useState([]);
  const [history, setHistory] = useState([]);
  const [activeTab, setActiveTab] = useState("status");
  const [newItem, setNewItem] = useState({ category: "", name: "", price: "" });
  const [theme, setTheme] = useState("dark");
  const [buttonColor, setButtonColor] = useState("#2563eb");
  const [textColor, setTextColor] = useState("#ffffff");
  const [font, setFont] = useState("inter");

  useEffect(() => {
    const allOrders = JSON.parse(localStorage.getItem("allOrders") || "[]");
    setOrders(allOrders.filter((o) => o.status !== "Fertig"));
    setHistory(allOrders.filter((o) => o.status === "Fertig"));
    setMenu(JSON.parse(localStorage.getItem("menuData") || "[]"));
    setTheme(localStorage.getItem("theme") || "dark");
    setButtonColor(localStorage.getItem("buttonColor") || "#2563eb");
    setTextColor(localStorage.getItem("textColor") || "#ffffff");
    setFont(localStorage.getItem("font") || "inter");

    const interval = setInterval(() => {
      const updatedOrders = JSON.parse(localStorage.getItem("allOrders") || "[]");
      setOrders(updatedOrders.filter((o) => o.status !== "Fertig"));
      setHistory(updatedOrders.filter((o) => o.status === "Fertig"));
    }, 3000);

    return () => clearInterval(interval);
  }, []);
  const updateOrderStatus = (index, status) => {
    const allOrders = JSON.parse(localStorage.getItem("allOrders") || "[]");
    const order = allOrders.find((_, i) => i === index);
    if (order) {
      order.status = status;
      allOrders[index] = order;
      localStorage.setItem("allOrders", JSON.stringify(allOrders));
      setOrders(allOrders.filter((o) => o.status !== "Fertig"));
      setHistory(allOrders.filter((o) => o.status === "Fertig"));

      const current = JSON.parse(localStorage.getItem("currentOrder") || "null");
      if (current && current.tableNumber === order.tableNumber && current.created === order.created) {
        localStorage.setItem("currentOrder", JSON.stringify(order));
      }
    }
  };

  const deleteOrder = (index) => {
    const allOrders = JSON.parse(localStorage.getItem("allOrders") || "[]");
    allOrders.splice(index, 1);
    localStorage.setItem("allOrders", JSON.stringify(allOrders));
    setOrders(allOrders.filter((o) => o.status !== "Fertig"));
    setHistory(allOrders.filter((o) => o.status === "Fertig"));
  };

  const minutesAgo = (timestamp) => {
    const now = new Date();
    const orderTime = new Date(timestamp);
    const diffMs = now - orderTime;
    return Math.round(diffMs / 60000);
  };

  const addItemToMenu = () => {
    if (!newItem.category || !newItem.name || !newItem.price) return;
    const updated = [...menu];
    const cat = updated.find((c) => c.category === newItem.category);
    if (cat) {
      cat.items.push({ name: newItem.name, price: parseFloat(newItem.price), available: true });
    } else {
      updated.push({ category: newItem.category, items: [{ name: newItem.name, price: parseFloat(newItem.price), available: true }] });
    }
    setMenu(updated);
    localStorage.setItem("menuData", JSON.stringify(updated));
    setNewItem({ category: "", name: "", price: "" });
  };

  const saveDesign = () => {
    localStorage.setItem("theme", theme);
    localStorage.setItem("buttonColor", buttonColor);
    localStorage.setItem("textColor", textColor);
    localStorage.setItem("font", font);
  };

  const getTop5Items = () => {
    const itemCounts = {};
    history.forEach((order) => {
      order.items.forEach((item) => {
        itemCounts[item.name] = (itemCounts[item.name] || 0) + item.quantity;
      });
    });
    return Object.entries(itemCounts)
      .sort((a, b) => b[1] - a[1])
      .slice(0, 5);
  };
  const totalRevenue = history.reduce(
    (sum, o) => sum + o.items.reduce((s, i) => s + i.price * i.quantity, 0),
    0
  );
  const avgOrderValue = history.length > 0 ? totalRevenue / history.length : 0;

  return (
    <div className="min-h-screen p-6 font-sans" style={{ fontFamily: font }}>
      <div className="flex gap-3 mb-6">
        {["status", "history", "menu", "design", "report"].map((tab) => (
          <button
            key={tab}
            className={`px-4 py-2 rounded ${
              activeTab === tab ? "bg-blue-600 text-white" : "bg-gray-300"
            }`}
            onClick={() => setActiveTab(tab)}
          >
            {tab.toUpperCase()}
          </button>
        ))}
      </div>

      {activeTab === "status" && (
        <div>
          <h2 className="text-2xl mb-4">Offene Bestellungen</h2>
          {orders.map((order, index) => (
            <div key={index} className="border p-4 mb-3 bg-white rounded shadow">
              <p><strong>Tisch:</strong> {order.tableNumber}</p>
              <p><strong>Zeit:</strong> vor {minutesAgo(order.created)} Min</p>
              <ul className="list-disc ml-6">
                {order.items.map((item, i) => (
                  <li key={i}>{item.name} × {item.quantity} – {item.price.toFixed(2)}€</li>
                ))}
              </ul>
              <div className="flex gap-2 mt-2">
                {["Ausstehend", "In Zubereitung", "Fertig"].map((status) => (
                  <button
                    key={status}
                    className="bg-blue-500 text-white px-2 py-1 rounded"
                    onClick={() => updateOrderStatus(index, status)}
                  >
                    {status}
                  </button>
                ))}
                <button
                  className="bg-red-500 text-white px-2 py-1 rounded"
                  onClick={() => deleteOrder(index)}
                >
                  Bestellung löschen
                </button>
              </div>
            </div>
          ))}
        </div>
      )}

      {activeTab === "history" && (
        <div>
          <h2 className="text-2xl mb-4">Abgeschlossene Bestellungen</h2>
          {history.map((order, index) => (
            <div key={index} className="border p-4 mb-3 bg-gray-100 rounded">
              <p><strong>Tisch:</strong> {order.tableNumber}</p>
              <p><strong>Zeit:</strong> vor {minutesAgo(order.created)} Min</p>
              <ul className="list-disc ml-6">
                {order.items.map((item, i) => (
                  <li key={i}>{item.name} × {item.quantity} – {item.price.toFixed(2)}€</li>
                ))}
              </ul>
            </div>
          ))}
        </div>
      )}

      {activeTab === "menu" && (
        <div>
          <h2 className="text-2xl mb-4">Speisekarte bearbeiten</h2>
          {menu.map((cat, catIndex) => (
            <div key={catIndex} className="mb-6">
              <div className="flex items-center justify-between">
                <h3 className="text-xl font-bold">{cat.category}</h3>
                <button
                  onClick={() => {
                    const updated = menu.filter((_, i) => i !== catIndex);
                    setMenu(updated);
                    localStorage.setItem("menuData", JSON.stringify(updated));
                  }}
                  className="text-red-600 text-sm"
                >
                  Kategorie löschen
                </button>
              </div>
              <ul>
                {cat.items.map((item, itemIndex) => (
                  <li key={itemIndex} className="flex gap-2 items-center mt-1">
                    <span>{item.name}</span>
                    <input
                      type="number"
                      value={item.price}
                      onChange={(e) => {
                        const updated = [...menu];
                        updated[catIndex].items[itemIndex].price = parseFloat(e.target.value);
                        setMenu(updated);
                        localStorage.setItem("menuData", JSON.stringify(updated));
                      }}
                      className="w-20 px-2 py-1 border rounded text-black"
                    />
                    <span>€</span>
                    <label className="ml-2">
                      <input
                        type="checkbox"
                        checked={item.available}
                        onChange={() => {
                          const updated = [...menu];
                          updated[catIndex].items[itemIndex].available = !item.available;
                          setMenu(updated);
                          localStorage.setItem("menuData", JSON.stringify(updated));
                        }}
                      />
                      verfügbar
                    </label>
                    <button
                      onClick={() => {
                        const updated = [...menu];
                        updated[catIndex].items.splice(itemIndex, 1);
                        setMenu(updated);
                        localStorage.setItem("menuData", JSON.stringify(updated));
                      }}
                      className="text-red-500 text-sm ml-2"
                    >
                      löschen
                    </button>
                  </li>
                ))}
              </ul>
            </div>
          ))}
          <div className="mt-4">
            <input
              placeholder="Kategorie"
              value={newItem.category}
              onChange={(e) => setNewItem({ ...newItem, category: e.target.value })}
              className="border px-2 py-1 mr-2"
            />
            <input
              placeholder="Name"
              value={newItem.name}
              onChange={(e) => setNewItem({ ...newItem, name: e.target.value })}
              className="border px-2 py-1 mr-2"
            />
            <input
              type="number"
              placeholder="Preis"
              value={newItem.price}
              onChange={(e) => setNewItem({ ...newItem, price: e.target.value })}
              className="border px-2 py-1 mr-2"
            />
            <button onClick={addItemToMenu} className="bg-green-500 text-white px-3 py-1 rounded">
              hinzufügen
            </button>
          </div>
        </div>
      )}

      {activeTab === "design" && (
        <div>
          <h2 className="text-2xl mb-4">Design ändern</h2>
          <select value={theme} onChange={(e) => setTheme(e.target.value)} className="border px-2 py-1 mr-2">
            {["dark", "light", "blue", "green", "techy", "edel", "minimal", "white", "cream", "contrast"].map((t) => (
              <option key={t} value={t}>{t}</option>
            ))}
          </select>
          <label className="block mt-2">
            Buttonfarbe:
            <input type="color" value={buttonColor} onChange={(e) => setButtonColor(e.target.value)} />
          </label>
          <label className="block mt-2">
            Schriftfarbe:
            <input type="color" value={textColor} onChange={(e) => setTextColor(e.target.value)} />
          </label>
          <label className="block mt-2">
            Schriftart:
            <select value={font} onChange={(e) => setFont(e.target.value)} className="border px-2 py-1">
              {["inter", "arial", "verdana", "georgia", "tahoma", "times", "courier", "roboto", "nunito", "poppins", "oxygen", "ubuntu", "lato", "montserrat", "open sans", "merriweather", "raleway", "fira sans", "exo", "rubik"].map((f) => (
                <option key={f} value={f}>{f}</option>
              ))}
            </select>
          </label>
          <button onClick={saveDesign} className="bg-blue-600 text-white px-4 py-2 mt-4 rounded">
            speichern
          </button>
        </div>
      )}

      {activeTab === "report" && (
        <div>
          <h2 className="text-2xl mb-4">Auswertung</h2>
          <p>Umsatz: {totalRevenue.toFixed(2)} €</p>
          <p>Ø Bestellwert: {avgOrderValue.toFixed(2)} €</p>
          <p className="mt-4 font-bold">Top 5 Artikel:</p>
          <ul className="list-disc ml-6">
            {getTop5Items().map(([name, count], i) => (
              <li key={i}>
                {name}: {count}× verkauft
              </li>
            ))}
          </ul>
        </div>
      )}
    </div>
  );
}
